metadata.query:
// Log records of one lab service in a window, grouped by severity.
fetch logs, from:"2026-09-19T08:24:05.705Z", to:"2026-09-19T08:24:09.911Z"
| filter service.namespace == "easytrade-otel-lab" and service.name == "broker-service"
| summarize records = count(), with_trace = countIf(isNotNull(trace_id)), by: {loglevel, status}
| sort records desc
